  const ks = []; for (let k = j.kneeFlex - 2.5*D2R; k > kEnd + 0.5*D2R; k -= 2.5*D2R) ks.push(k); ks.push(kEnd);
  /* near lockout the efforts are small, and lowest effort alone would lean the trunk back behind the hips to stack the load over
     the joints; people stand tall instead. Leaning back costs a fixed share of the junction's effort, so it only decides the
     posture where effort no longer does. */
  const ev = (kap, z)=>{ const r = evalSquatK(b, set, prep, kap, z, pole, goal); if (r.fail || r.thetaS > tMax) return null;
    r.tMax = tMax; r.beta = j.beta; r.ankleUse = r.thetaS/tMax; r.ankleBound = false;
    r.cost += j.cost*0.5*(Math.max(0, -r.t)/(5*D2R))**2; return r; };
