    const w = m.L0*Math.sin(m.pen), cl = LEN[m.g], dl = cl ? cl[0] : 0, kp = cl ? cl[1] : 1; let lt = 1, lfc = 0, lf = 0;
    for (let i = 0; i < 3; i++){ lfc = Math.max(1e-4, Lmt - m.Lts*(1 + 0.033*FL(lt))); lf = Math.sqrt(lfc*lfc + w*w); lt = 1 + (lf/m.L0 - 1)/kp + dl; }
    return {lt, cosa: lfc/lf};
