  /* ---------- hip angles from pelvis and femur frames (model frame), Z-X-Y order as in the model */
  function hipQ(px, py, pz, fx, fy, fz){
    const R01 = dot(px, fy), R11 = dot(py, fy), R21 = dot(pz, fy), R20 = dot(pz, fx), R22 = dot(pz, fz);
    return [Math.atan2(-R01, R11), Math.asin(clamp(R21, -1, 1)), Math.atan2(-R20, R22)];
  }
