  const QLIM = [[-28*D2R, 128*D2R], [-48*D2R, 28*D2R], [-38*D2R, 38*D2R]];
  const qClamp = q=>q.map((v,i)=>clamp(v, QLIM[i][0], QLIM[i][1]));
