    const yF = nrm(os(sub(g.Hr, g.K))), eO = os(e), zF = nrm(sub(eO, mul(yF, dot(eO, yF)))), xF = cross(yF, zF);
    const yP = nrm(os(g.uP)), zP0 = v3(0,0,1), zP = nrm(sub(zP0, mul(yP, dot(zP0, yP)))), xP = cross(yP, zP);
    const q = hipQ(xP, yP, zP, xF, yF, zF), qc = qClamp(q), L = hipL(qc);
