function runChecks(){ return CHECKS.map(c=>{ try{ return Object.assign({id:c.id, group:c.group, name:c.name, expect:c.expect, src:c.src}, c.run()); }catch(e){ return {id:c.id, group:c.group, name:c.name, expect:c.expect, pass:false, value:"error: "+e.message}; } }); }
ENGINE.CHECKS = CHECKS; ENGINE.runChecks = runChecks;

ENGINE.MUS = MUS;
G.SLSimEngine = ENGINE;
if (typeof document === "undefined") return;     // engine only (tests)
