const vPct = (a, q)=>{ const s = a.slice().sort((x,y)=>x-y); return s[Math.min(s.length-1, Math.max(0, Math.round(q*(s.length-1))))]; };
const vAng = (dx, dy)=>Math.atan2(dx, dy)*R2D;                      // angle from vertical, + toward facing direction
