  const conf = F.reduce((a,f)=>a + ["sho","hip","kne","ank"].reduce((c,k)=>c + f.kp[VK[k][sd]].s, 0)/4, 0)/F.length;
  const facing = vPct(F.map((f,i)=>J.nose[i].x - J.ear[i].x), 0.5) >= 0 ? 1 : -1;
