  if (!(ppm > 20)) return {err:"Couldn't find your legs clearly. Film from the side with your whole body in view."};
  const ax = vPct(J.ank.map(p=>p.x), 0.5), ay = vPct(J.ank.map(p=>p.y), 0.5);
  const W2 = p=>({x: facing*(p.x - ax)/ppm, y: (ay - p.y)/ppm});        // metres: x forward from the ankle, y up from the ankle
  const P = {}; Object.keys(J).forEach(k=>{ P[k] = J[k].map(W2); });
