  const sig = (mv==="dead"||mv==="rdl"||mv==="bench"||mv==="ohp") ? P.wri.map(p=>p.y) : mv==="row" ? P.wri.map((p,i)=>-Math.hypot(p.x - P.sho[i].x, p.y - P.sho[i].y)) : mv==="pull" ? P.sho.map(p=>p.y) : P.hip.map(p=>p.y);
