  if (!reps.length) return {err:"Couldn't split the set into reps. Film a full rep from start to finish.", ppm, facing, P, t, conf};
  // the top each lowering-first rep comes back up to: the next rep's start, or the highest point after the last one
  if (ecc) reps.forEach((r, k)=>{ if (reps[k+1]) r.iTop = reps[k+1].i0; else { let m = r.i1; for (let i = r.i1; i < sig.length; i++){ if (sig[i] > sig[m]) m = i; if (sig[i] < sig[m] - 0.3*R) break; } r.iTop = m; } });
