  if (loss!=null){ const g = C.goal; L.push([loss > 0.4 ? "w" : "", "Speed", "Speed dropped "+Math.round(loss*100)+"% from the fastest rep to the last."+(g==="power" ? (loss > 0.2 ? " For power, stop sets at about 10–20% loss." : " That's in the range for power work.") : g==="strength" ? " Stopping near 20% loss gives strength gains with less fatigue (Pareja-Blanco 2017)." : "")]); }
