  const q0 = n=>{ try{ return best ? best(n) : null; }catch(e){ return null; } };
  const fmtB = q => q.w+"×"+q.reps+(q.date ? " on "+q.date.slice(5).replace("-","/") : "");
  if (mv==="squat" && oneRM.squat) return {lb:oneRM.squat, src:"working max from your log"};
  if (mv==="dead" && oneRM.dead) return {lb:oneRM.dead, src:"working max from your log"};
  if (mv==="bench" && oneRM.bench) return {lb:oneRM.bench, src:"working max from your log"};
  if (mv==="ohp" && oneRM.ohp) return {lb:oneRM.ohp, src:"working max from your log"};
  if (mv==="frontsq") return {lb:lr5((oneRM.squat||315)*0.8), src:"estimated as 80% of your squat"};
  if (mv==="rdl"){ const q = q0("RDL"); if (q) return {lb:lr5(q.e), src:"best logged set "+fmtB(q)}; return {lb:lr5((oneRM.dead||365)*0.65), src:"estimated as 65% of your deadlift"}; }
  if (mv==="row"){ const q = q0("Bent-over row"); if (q) return {lb:lr5(q.e), src:"best logged set "+fmtB(q)}; return {lb:lr5((oneRM.bench||225)*0.6), src:"estimated as 60% of your bench"}; }
  if (mv==="pull"){ const q = q0("Weighted pull-up"); if (q) return {lb:lr5(q.e), src:"best logged set "+(q.w>0?"+":"")+q.w+"×"+q.reps+" (bodyweight + added)"}; return {lb:lr5(bwLb*1.25), src:"estimated as bodyweight + 25%"}; }
