/* the setup you marked in Build as how you actually lift (Build's other settings are experiments and never reach the log);
   without one, the standard setup */
const mineRec = (rec, mv)=> rec && rec.mine && rec.mine[mv] && rec.mine[mv].s ? rec.mine[mv] : null;
const logSetup = (rec, mv)=> Object.assign({}, MOVES[mv].defaults, (mineRec(rec, mv) || {}).s || {});
const logGoal = (rec, mv)=>{ const m = mineRec(rec, mv), g = m && m.g; return g && MOVES[mv].goals.includes(g) ? g : MOVES[mv].goals[0]; };

/* ---------- the setup you saved in Build, as a cue you can act on at the bar ---------- */
