    o.plumb = B.plumb && A.plumb ? {z:A.plumb.z*(1-m) + B.plumb.z*m, y0:A.plumb.y0*(1-m) + B.plumb.y0*m, y1:A.plumb.y1*(1-m) + B.plumb.y1*m} : B.plumb;
    o.levers = B.levers.map((lv,i)=>A.levers[i] ? {j:lv.j, p:L(A.levers[i].p, lv.p), refZ:A.levers[i].refZ*(1-m) + lv.refZ*m} : lv);
