      bar = {c:r.bar, plateR:0.225, half:1.1};
      levers = mv==="rdl" ? [{j:"hip", p:r.Hr, refZ:r.bar.z}, {j:"back", p:sp.L5, refZ:r.bar.z}] : [{j:"sh", p:r.G, refZ:r.bar.z}, {j:"back", p:sp.L5, refZ:r.bar.z}];
