      props = [{t:"box", min:v3(-0.14, bg.yb - 0.08, -0.32), max:v3(0.14, bg.yb, bg.P.z + 0.18)}, {t:"box", min:v3(-0.04, 0, -0.18), max:v3(0.04, bg.yb - 0.08, -0.1)}, {t:"box", min:v3(-0.04, 0, bg.P.z - 0.05), max:v3(0.04, bg.yb - 0.08, bg.P.z + 0.03)}];
